// Turns a title written for humans into a query Spotify can use.
// My choice: (Remix), (Live) and (Acoustic) are KEPT, because they're a
// different version of the song, not noise.

// A group (...) or [...] counts as noise if it contains one of these words.
// (some are French because a lot of the titles I get are French)
const JUNK = ['official', 'officiel', 'officielle', 'video', 'vidéo', 'clip',
  'lyric', 'lyrics', 'paroles', 'audio', 'visualizer', 'visualiser',
  'hd', 'hq', '4k', 'remaster', 'remastered', 'mv'];

const isJunk = inside => {
  const low = inside.toLowerCase();
  return JUNK.some(w => new RegExp(`(^|[^a-zà-ÿ])${w}([^a-zà-ÿ]|$)`).test(low));
};

// What gets sent to Spotify: "Artist x Artist" becomes "Artist Artist",
// and the brackets go away (they mess up the search).
const forSearch = s => s.replace(/\s+[x×]\s+/gi, ' ').replace(/[()\[\]]/g, ' ').replace(/\s+/g, ' ').trim();

return $input.all().map(item => {
  const raw = item.json.rawTitle || '';
  let t = raw;

  // 1. groups (...) or [...] containing a noise word
  t = t.replace(/[(\[]([^)\]]*)[)\]]/g, (whole, inside) => (isJunk(inside) ? ' ' : whole));

  // 1b. guest groups: (with X), (feat. X), [ft. X]
  t = t.replace(/[(\[]\s*(?:with|feat|ft|featuring)\.?\s[^)\]]*[)\]]/gi, ' ');

  // 2. featurings "ft. X" / "feat. X", up to the next separator or the end
  t = t.replace(/\s(?:ft|feat|featuring)\.?\s.*?(?=\s[-–—]\s|$)/gi, ' ');

  // 3. channel suffixes after a vertical bar: "| Official Video"
  t = t.replace(/\s[|｜].*$/, ' ');

  // 4. emojis, decorative symbols, quotes
  t = t.replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, ' ');
  t = t.replace(/["“”«»]/g, ' ');

  // 5. extra spaces
  t = t.replace(/\s+/g, ' ').trim();
    // a dash left alone at the end (after removing (Clip officiel)) has to go too
  t = t.replace(/\s+[-–—]\s*$/, '').trim();

  // 5b. noise words stuck at the END without brackets: "... MISS KITOKO VISUALIZER", "... Official Video"
  //     (I always keep at least one word of the track)
  const END_JUNK = ['official', 'officiel', 'officielle', 'video', 'vidéo', 'clip', 'lyric', 'lyrics', 'paroles',
    'audio', 'visualizer', 'visualiser', 'hd', 'hq', '4k', 'mv'];
  const words = t.split(' ');
  let removed = false;
  while (words.length > 2) {
    const last = words[words.length - 1].toLowerCase();
    const prev = words[words.length - 2];
    if (prev === '-' || prev === '–' || prev === '—') break;      // never eat the whole track name
    if (END_JUNK.includes(last) || (removed && last === 'music')) { words.pop(); removed = true; }
    else break;
  }
  t = words.join(' ');

  // 6. split artist and track on a dash WITH spaces around it
  //    (a dash stuck to the word doesn't count, "Jay-Z" has to stay whole)
  const parts = t.split(/\s[-–—]\s/);
  const hasSeparator = parts.length >= 2;
  const artist = hasSeparator ? parts[0].trim() : '';
  const track = hasSeparator ? parts.slice(1).join(' ').trim() : t;

  return {
    json: {
      rawTitle: raw,
      cleanTitle: t,
      artist,
      track,
      hasSeparator,
      query: forSearch([artist, track].filter(Boolean).join(' ')),
    },
  };
});

// MAIN TRAP: Spotify NEVER returns zero results.
// Even a nonsense search brings back unrelated tracks.
// So a result only gets accepted if it really matches the YouTube title.
//
// The rule: an artist returned by Spotify must appear in the YouTube title,
// AND the track name must match the video's track too
// (otherwise any other song by the same artist would get accepted).

const norm = s => String(s || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')   // remove accents
  .replace(/[^a-z0-9]+/g, ' ')                         // punctuation -> space
  .trim();

// The whole word has to appear, not a piece of it ("Mo" must not match "Moby")
const contains = (hay, needle) => {
  const n = norm(needle);
  return n.length > 0 && (' ' + hay + ' ').includes(' ' + n + ' ');
};

// Spotify name without "- Remastered 2009" or "(feat. X)"
const coreName = name => String(name || '').split(' - ')[0].replace(/\s*[(\[].*?[)\]]/g, '');

// The search returns exactly one result per title, in the same order:
// the i-th result matches the i-th cleaned title.
const sources = $('Clean titles').all();

return $input.all().map((res, i) => {
  const src = sources[i].json;
  if (!src.rawTitle) return { json: { rawTitle: '', status: 'not found' } };          // private or deleted video
  if (res.json.error) return { json: { rawTitle: src.rawTitle, status: 'error' } };   // Spotify didn't answer
  const hay = norm(src.rawTitle);

  // "MIKL" (YouTube) vs "Mik L" (Spotify): I also compare the names stuck together,
  // but only on consecutive WHOLE words of the title (never a piece of a word).
  const tokens = hay.split(' ').filter(Boolean);
  const joinedMatch = name => {
    const target = norm(name).replace(/ /g, '');
    if (target.length < 3) return false;
    for (let a = 0; a < tokens.length; a++) {
      let s = '';
      for (let b = a; b < Math.min(a + 4, tokens.length); b++) {
        s += tokens[b];
        if (s === target) return true;
        if (s.length > target.length) break;
      }
    }
    return false;
  };
  const artistMatches = name => contains(hay, name) || joinedMatch(name);
  const candidates = res.json.tracks?.items || [];

  // The TRACK has to match, not only the artist.
  // Every word of the Spotify name must be in the video's track, and make up at least
  // 60% of its words (so "Home" doesn't validate "Take Me Home").
  // I try the full name first, then the name without "(feat. ...)" or "- Remastered".
  const ytWords = norm(src.track ?? '').split(' ').filter(Boolean);
  const nameMatches = spotifyName => [norm(spotifyName), norm(coreName(spotifyName))].some(variant => {
    const words = variant.split(' ').filter(Boolean);
    return words.length > 0 && ytWords.length > 0
      && words.every(w => ytWords.includes(w))
      && words.length / ytWords.length >= 0.6;
  });

  const match = candidates.find(track =>
    (track.artists || []).some(a => artistMatches(a.name)) && nameMatches(track.name));

  if (!match) {
    // keep what Spotify offered, to understand WHY it was refused
    const candidatesSeen = candidates.slice(0, 10).map(t =>
      `${(t.artists || []).map(a => a.name).join(', ')} — ${t.name}`);
    // the first 3 candidates with their URI: this is what the review queue will offer
    const proposals = candidates.slice(0, 3).map(t => ({
      uri: t.uri,
      label: `${(t.artists || []).map(a => a.name).join(', ')} — ${t.name}`,
    }));
    return { json: { rawTitle: src.rawTitle, status: 'not found', hasSeparator: src.hasSeparator, candidatesSeen, candidates: proposals } };
  }
  return {
    json: {
      rawTitle: src.rawTitle,
      status: 'found',
      uri: match.uri,
      name: match.name,
      artist: match.artists.map(a => a.name).join(', '),
    },
  };
});

// SECOND CHANCE: same rules as "Check the match", but on what the AI understood from the title.
// MAIN TRAP: Spotify NEVER returns zero results.
// Even a nonsense search brings back unrelated tracks.
// So a result only gets accepted if it really matches the YouTube title.
//
// The rule: an artist returned by Spotify must appear in the YouTube title,
// AND the track name must match the video's track too
// (otherwise any other song by the same artist would get accepted).

const norm = s => String(s || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')   // remove accents
  .replace(/[^a-z0-9]+/g, ' ')                         // punctuation -> space
  .trim();

// The whole word has to appear, not a piece of it ("Mo" must not match "Moby")
const contains = (hay, needle) => {
  const n = norm(needle);
  return n.length > 0 && (' ' + hay + ' ').includes(' ' + n + ' ');
};

// Spotify name without "- Remastered 2009" or "(feat. X)"
const coreName = name => String(name || '').split(' - ')[0].replace(/\s*[(\[].*?[)\]]/g, '');

// The search returns exactly one result per title, in the same order:
// the i-th result matches the i-th cleaned title.
const sources = $('Read the AI answer').all();

return $input.all().map((res, i) => {
  const src = sources[i].json;
  if (!src.rawTitle) return { json: { rawTitle: '', status: 'not found' } };          // private or deleted video
  if (res.json.error) return { json: { rawTitle: src.rawTitle, status: 'error' } };   // Spotify didn't answer
  const hay = norm(src.rawTitle);

  // "MIKL" (YouTube) vs "Mik L" (Spotify): I also compare the names stuck together,
  // but only on consecutive WHOLE words of the title (never a piece of a word).
  const tokens = hay.split(' ').filter(Boolean);
  const joinedMatch = name => {
    const target = norm(name).replace(/ /g, '');
    if (target.length < 3) return false;
    for (let a = 0; a < tokens.length; a++) {
      let s = '';
      for (let b = a; b < Math.min(a + 4, tokens.length); b++) {
        s += tokens[b];
        if (s === target) return true;
        if (s.length > target.length) break;
      }
    }
    return false;
  };
  const artistMatches = name => contains(hay, name) || joinedMatch(name);
  const candidates = res.json.tracks?.items || [];

  // Extra guard for the AI's second chance: every word of the Spotify track name has to be
  // in the ORIGINAL title too. So the AI can never make me add a song that isn't in the title.
  const inTitle = n => [norm(n), norm(coreName(n))].some(v => v && v.split(' ').every(w => tokens.includes(w)));

  // The TRACK has to match, not only the artist.
  // Every word of the Spotify name must be in the video's track, and make up at least
  // 60% of its words (so "Home" doesn't validate "Take Me Home").
  // I try the full name first, then the name without "(feat. ...)" or "- Remastered".
  const ytWords = norm(src.track ?? '').split(' ').filter(Boolean);
  const nameMatches = spotifyName => [norm(spotifyName), norm(coreName(spotifyName))].some(variant => {
    const words = variant.split(' ').filter(Boolean);
    return words.length > 0 && ytWords.length > 0
      && words.every(w => ytWords.includes(w))
      && words.length / ytWords.length >= 0.6;
  });

  const match = candidates.find(track =>
    (track.artists || []).some(a => artistMatches(a.name)) && nameMatches(track.name) && inTitle(track.name));

  if (!match) {
    // keep what Spotify offered, to understand WHY it was refused
    const candidatesSeen = candidates.slice(0, 10).map(t =>
      `${(t.artists || []).map(a => a.name).join(', ')} — ${t.name}`);
    // the first 3 candidates with their URI: this is what the review queue will offer
    const proposals = candidates.slice(0, 3).map(t => ({
      uri: t.uri,
      label: `${(t.artists || []).map(a => a.name).join(', ')} — ${t.name}`,
    }));
    return { json: { rawTitle: src.rawTitle, status: 'not found', hasSeparator: src.hasSeparator, candidatesSeen, candidates: proposals } };
  }
  return {
    json: {
      rawTitle: src.rawTitle,
      status: 'found',
      uri: match.uri,
      name: match.name,
      artist: match.artists.map(a => a.name).join(', '),
    },
  };
});

// Which titles did my rules refuse? Only those go to the AI:
// it's cheap, and my rules stay the boss (they check whatever the AI says).
const MAX_AI = 10;   // safety cap per run (AI plans have rate limits)
const results = $input.all().map(i => i.json);
const refused = results
  .filter(r => r.status === 'not found' && r.rawTitle)
  .slice(0, MAX_AI)
  .map(r => ({ rawTitle: r.rawTitle }));
return [{ json: { retry: refused.length > 0, refused } }];

// The AI answers with a little JSON: { "artist": "...", "track": "..." }.
// I read it carefully, because an AI doesn't always answer exactly as asked.
const titles = $('One title per row').all().map(i => i.json.rawTitle);
const forSearch = s => s.replace(/\s+[x×]\s+/gi, ' ').replace(/[()\[\]]/g, ' ').replace(/\s+/g, ' ').trim();

return $input.all().map((item, i) => {
  const rawTitle = titles[i];
  let artist = '', track = '';
  try {
    const text = String(item.json.text ?? item.json.output ?? '');
    const found = text.match(/\{[\s\S]*\}/);          // the JSON part, even if the AI added ```json or words around it
    const answer = JSON.parse(found[0]);
    artist = String(answer.artist || '').trim();
    track = String(answer.track || '').trim();
  } catch (e) { /* the AI failed or didn't answer in JSON: both stay empty */ }

  return { json: {
    rawTitle,
    artist,
    track,
    hasSeparator: !!(artist && track),
    query: forSearch([artist, track].filter(Boolean).join(' ')) || forSearch(rawTitle),
  } };
});

// Puts the AI's second chance back into the first results, in the original order.
const first = $('Check the match').all().map(i => i.json);
const second = new Map($('Check again').all().map(i => [i.json.rawTitle, i.json]));

return first.map(r => {
  const again = r.status === 'not found' ? second.get(r.rawTitle) : null;
  if (!again) return { json: r };                                    // nothing changed for this title
  if (again.status === 'found') return { json: { ...again, rescuedByAI: true, aiTried: true } };
  // still refused: I keep the AI's candidates, they are usually better suggestions for /review
  return { json: {
    ...r,
    aiTried: true,
    hasSeparator: again.hasSeparator || r.hasSeparator,
    candidates: again.candidates?.length ? again.candidates : r.candidates,
    candidatesSeen: again.candidatesSeen ?? r.candidatesSeen,
  } };
});
